#include "NameEntryScene.hpp"
#include <algorithm>
#include <cmath>
namespace th075 {
void NameEntryScene::poll(const MenuInput& input,const std::array<i32,2>& quickEnd,SceneSignals& signals){const auto repeat=[](i32 n,i32 direction){return n==direction||(n%6==direction&&(direction>0?n>30:n< -30));};for(u8 side=0;side<2;side++){if(repeat(input.horizontal[side],1)){signals.sound(39);column++;if(replay)yesNo=i16(1-yesNo);}if(repeat(input.horizontal[side],-1)){signals.sound(39);column--;if(replay)yesNo=i16(1-yesNo);}if(repeat(input.vertical[side],1)){signals.sound(39);row++;}if(repeat(input.vertical[side],-1)){signals.sound(39);row--;}if(quickEnd[side]==1){column=14;row=3;}}action=input.confirm[0]==1||input.confirm[1]==1?1:input.cancel[0]==1||input.cancel[1]==1?2:0;if(row<0)row=3;if(row>3)row=0;if(row<3){if(column<0)column=25;if(column>25)column=0;}else {if(column<0)column=14;if(column>14)column=14;}}
u16 NameEntryScene::advance(std::array<u8,8>& name,bool recording,i8 disposition,NameEntrySignals& signals){if(!replay||!skip){if(action==1){signals.sound(45);const auto code=column+row*26;if(code==92){if(replay){if(recording)signals.save_replay_name();return 0x2202;}signals.save_score_name(rank);return disposition!=0?0x2207:0x2202;}name[std::clamp<i16>(position,0,7)]=code==91?100:u8(code);position++;if(position>8)position=8;if(position==8){column=14;row=3;}}if(action==2){signals.sound(40);position--;if(!replay&&position<0)position=0;if(position>=0)name[position]=100;if(replay&&position<0){skip=true;position=0;}}}else if(action==1){signals.sound(45);if(yesNo!=0)return 0x2202;skip=false;column=row=0;}signals.render_name_entry();signals.present_name_entry();return replay?7:10;}
void NameEntryScene::render_score(ImageRenderer& images,const std::array<ScoreRank,10>& ranking,u32 now)const{images.graphics.depth(DepthMode::Disabled);images.blend(SpriteBlend::Alpha);MenuDrawing::region(images,0,{0,0,640,480},0,0,640,480);MenuDrawing::region(images,1,{192,128,512,160},160,10,480,42);MenuDrawing::region(images,2,{0,80,500,160},70,300,570,380);const float pulse=float(std::sin(double(float(double(float(now))/100.0)))*.25+1.25);const auto cursor=[&](float x,float y){const CollisionRectangle r{column*19,row*20+160,column*19+19,row*20+180};auto q=rectangle_quad(0,0,19,20);scale_quad(q,10,10,0,pulse,pulse,1);translate_quad(q,x,y,0);images.quad(2,q,r,0xffffffff);};cursor(float(column*19+70),float(row*20+300));for(u8 i=0;i<10;i++){const u32 color=i==rank?0xffffffff:0xff808080;const float y=float(i*20+80);const auto& r=ranking[i];MenuDrawing::slot(images,80,y,color,i+1);MenuDrawing::name(images,160,y,color,r.name);MenuDrawing::digits(images,330,y,color,i8(r.month),2);MenuDrawing::region(images,2,{228,40,247,60},325,y,344,y+20,color);MenuDrawing::digits(images,370,y,color,i8(r.day),2);MenuDrawing::digits(images,560,y,color,i32(r.score));}if(position<8&&column+row*26!=92)cursor(float(position*14+160),float(rank*20+80));}
void NameEntryScene::render_replay(ImageRenderer& images,const ReplayFile& replayFile,const std::string& filename,u8 otherCharacter,u32 now)const{images.graphics.depth(DepthMode::Disabled);images.blend(SpriteBlend::Alpha);MenuDrawing::region(images,0,{0,0,640,480},0,0,640,480);MenuDrawing::region(images,1,{192,160,512,192},160,20,480,52);if(skip){MenuDrawing::region(images,1,{200,20,460,60},190,200,450,240);const i32 l=yesNo==0?320:192;MenuDrawing::region(images,1,{l,192,l+128,224},256,280,384,312);return;}const float pulse=float(std::sin(double(float(double(float(now))/100.0)))*.25+1.25);const auto cursor=[&](float x,float y){auto q=rectangle_quad(0,0,19,20);scale_quad(q,10,10,0,pulse,pulse,1);translate_quad(q,x,y,0);images.quad(2,q,{column*19,row*20+160,column*19+19,row*20+180},0xffffffff);};MenuDrawing::region(images,2,{0,80,500,160},70,300,570,380);cursor(float(column*19+70),float(row*20+300));MenuDrawing::region(images,1,{0,0,512,20},64,100,576,120);MenuDrawing::replay_file(images,50,130,0xffffffff,filename);std::array<u8,8> name;std::copy_n(replayFile.header.data(),8,name.data());MenuDrawing::name(images,160,130,0xffffffff,name);if(position<8&&column+row*26!=92)cursor(float(position*14+160),130);MenuDrawing::digits(images,330,130,0xffffffff,i8(replayFile.header[8]),2);MenuDrawing::region(images,2,{228,40,247,60},325,130,344,150);MenuDrawing::digits(images,370,130,0xffffffff,i8(replayFile.header[9]),2);if(replayFile.header[13]==0){const i32 t=otherCharacter*20+20;MenuDrawing::region(images,1,{0,t,100,t+20},416,144,516,158,0xffb0b0b0);}const i32 t=i8(replayFile.header[10])*20+20,m=i8(replayFile.header[13])*20+20;MenuDrawing::region(images,1,{0,t,100,t+20},380,130,480,150);MenuDrawing::region(images,1,{100,m,180,m+20},500,130,580,150);}
}
